import { MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import {
  uv, color, mix, smoothstep, clamp, float, vec2, abs, max, length, step,
  positionLocal, uniform
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, Shape, ExtrudeGeometry, PlaneGeometry, PointLight } = ctx.THREE;

  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? {};
  const BG = colors.background ?? '#0b0b10';
  const SURFACE = colors.surface ?? '#16161d';
  const INK = colors.ink ?? '#16161d';
  const PAPER = colors.paper ?? '#e8ecf2';
  const ACCENT = colors.accent ?? '#ff2a38';
  const stops = colors.gradientStops ?? [
    { at: 0, hex: '#ff4450' }, { at: 0.55, hex: '#ff2a38' }, { at: 1, hex: '#c1121f' }
  ];

  const root = new Group();
  const timelines = [];
  const disposables = [];
  const primitiveHandles = [];

  // ---------------------------------------------------------------
  // BACKDROP STAGE (depth plane 1) — dark engineered vertical gradient
  // ---------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  {
    const vy = uv().y;
    const centered = uv().sub(0.5).mul(vec2(1.166, 1.0)); // aspect-normalize
    const dist = length(centered);
    const radialLift = smoothstep(float(0.75), float(0.05), dist);
    const base = mix(color(BG), color(SURFACE), vy.mul(0.7));
    backdropMat.colorNode = mix(base, color(SURFACE), radialLift.mul(0.85));
  }
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------------------------------------------------------------
  // CONTENT GROUP (scaled to fill hub frame)
  // ---------------------------------------------------------------
  const content = new Group();
  content.scale.setScalar(1.4);
  root.add(content);

  const floatGroup = new Group(); // idle float wrapper
  content.add(floatGroup);

  const buttonGroup = new Group(); // hover z / press scale target
  floatGroup.add(buttonGroup);

  // ---------------------------------------------------------------
  // BUTTON BODY (depth plane 2) — extruded rounded rect, chamfer bevel
  // ---------------------------------------------------------------
  const W = 2.6, H = 0.68, R = 0.08, DEPTH = 0.03, BEVEL = 0.02;

  const shape = new Shape();
  const hw = W / 2, hh = H / 2;
  shape.moveTo(-hw + R, -hh);
  shape.lineTo(hw - R, -hh);
  shape.quadraticCurveTo(hw, -hh, hw, -hh + R);
  shape.lineTo(hw, hh - R);
  shape.quadraticCurveTo(hw, hh, hw - R, hh);
  shape.lineTo(-hw + R, hh);
  shape.quadraticCurveTo(-hw, hh, -hw, hh - R);
  shape.lineTo(-hw, -hh + R);
  shape.quadraticCurveTo(-hw, -hh, -hw + R, -hh);

  const btnGeo = new ExtrudeGeometry(shape, {
    depth: DEPTH,
    bevelEnabled: true,
    bevelThickness: BEVEL,
    bevelSize: BEVEL,
    bevelSegments: 2, // 45deg machined chamfer read
    curveSegments: 12
  });
  btnGeo.center();

  const btnMat = new MeshPhysicalNodeMaterial({
    roughness: 0.5,
    metalness: 0.35,
    clearcoat: 0.22,
    clearcoatRoughness: 0.4
  });
  {
    // vertical engineered gradient: at=0 top -> at=1 bottom
    const t = clamp(positionLocal.y.div(float(H)).add(0.5), float(0), float(1)); // 0 bottom, 1 top
    const s = float(1).sub(t); // 0 at top, 1 at bottom
    const c0 = color(stops[0].hex);
    const c1 = color(stops[1]?.hex ?? stops[0].hex);
    const c2 = color(stops[2]?.hex ?? stops[1]?.hex ?? stops[0].hex);
    const seg1 = clamp(s.div(float(0.55)), float(0), float(1));
    const seg2 = clamp(s.sub(float(0.55)).div(float(0.45)), float(0), float(1));
    let ramp = mix(c0, c1, seg1);
    ramp = mix(ramp, c2, seg2);
    // hard 0.01-unit seam at 50% face height, zero blur
    const seamMask = step(abs(positionLocal.y), float(0.005));
    btnMat.colorNode = mix(ramp, ramp.mul(0.76), seamMask);
  }
  const button = new Mesh(btnGeo, btnMat);
  buttonGroup.add(button);
  disposables.push(btnGeo, btnMat);

  // ---------------------------------------------------------------
  // PERIMETER EMISSIVE CHANNEL — 0.015-wide accent ring on the face
  // ---------------------------------------------------------------
  const edgeIntensity = uniform(1.6);
  const frameGeo = new PlaneGeometry(W, H);
  const frameMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  {
    const p = uv().sub(0.5).mul(vec2(W, H));
    const q = abs(p).sub(vec2(hw - R, hh - R));
    const d = length(max(q, vec2(0, 0))).sub(float(R)); // rounded-rect SDF (edge-accurate)
    const band = step(d, float(0)).mul(step(float(-0.015), d)); // -0.015 <= d <= 0
    frameMat.colorNode = color(ACCENT).mul(edgeIntensity);
    frameMat.opacityNode = band;
  }
  const frame = new Mesh(frameGeo, frameMat);
  frame.position.z = DEPTH / 2 + BEVEL + 0.004;
  buttonGroup.add(frame);
  disposables.push(frameGeo, frameMat);

  // ---------------------------------------------------------------
  // CONTACT SHADOW — 0.08 below, 35% opacity, tightens on press
  // ---------------------------------------------------------------
  const shadowOpacity = uniform(0.35);
  const shadowGeo = new PlaneGeometry(3.4, 1.2);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  {
    const d = length(uv().sub(0.5).mul(vec2(2, 2)));
    shadowMat.colorNode = color('#000000');
    shadowMat.opacityNode = smoothstep(float(1), float(0.15), d).mul(shadowOpacity);
  }
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -(hh + 0.08), -0.09);
  floatGroup.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // ---------------------------------------------------------------
  // TEXT — verbatim spec copy via font atlas
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const role = item.role ?? '';
    const fs = item.typography?.fontSize ?? (role === 'caption' ? 9 : 20);
    if (role === 'cta-label' || (role !== 'caption' && fs >= 14)) {
      const label = ctx.fontAtlas.createText(String(item.text), {
        fontSize: fs,
        color: INK,
        align: 'center',
        letterSpacingPx: fs * 0.08
      });
      label.position.set(0, 0, DEPTH / 2 + BEVEL + 0.02);
      buttonGroup.add(label);
    } else {
      const caption = ctx.fontAtlas.createText(String(item.text), {
        fontSize: fs,
        color: PAPER,
        align: 'center',
        letterSpacingPx: fs * 0.12
      });
      caption.position.set(0, -(hh + 0.25), 0.02);
      floatGroup.add(caption);
    }
  }

  // ---------------------------------------------------------------
  // FOREGROUND ACCENT TICK (depth plane 3)
  // ---------------------------------------------------------------
  const tickGeo = new PlaneGeometry(0.28, 0.014);
  const tickMat = new MeshBasicNodeMaterial();
  tickMat.colorNode = color(ACCENT);
  const tick = new Mesh(tickGeo, tickMat);
  tick.position.set(0, -(hh + 0.42), 0.3);
  floatGroup.add(tick);
  disposables.push(tickGeo, tickMat);

  // ---------------------------------------------------------------
  // NODE-LOCAL RIM LIGHT — accent hue, opposite the scene key
  // ---------------------------------------------------------------
  const rim = new PointLight(ACCENT, 1.2, 12);
  rim.position.set(-2.4, -1.2, 1.6);
  root.add(rim);
  const fill = new PointLight(PAPER, 0.5, 12);
  fill.position.set(2.2, 1.8, 2.4);
  root.add(fill);

  // ---------------------------------------------------------------
  // MOTION — weighted settle mount, single idle breath
  // ---------------------------------------------------------------
  const mountTl = gsap.timeline();
  buttonGroup.scale.setScalar(1.04);
  floatGroup.position.y = 0.2;
  mountTl.to(buttonGroup.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0);
  mountTl.to(floatGroup.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);
  timelines.push(mountTl);

  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(floatGroup.position, { z: 0.03, duration: 3.2, ease: 'sine.inOut' });
  timelines.push(idleTl);

  // ---------------------------------------------------------------
  // CINEMATIC PRIMITIVES (spec ships none; honor any provided)
  // ---------------------------------------------------------------
  for (const prim of config.cinematicPrimitives ?? []) {
    const handle = ctx.primitives[prim.name](buttonGroup, prim.params);
    if (handle) primitiveHandles.push(handle);
  }

  // ---------------------------------------------------------------
  // INTERACTION
  // ---------------------------------------------------------------
  let pressed = false;
  root.userData.handlers = {
    onPointerOver: () => {
      gsap.to(buttonGroup.position, { z: 0.06, duration: 0.18, ease: 'power2.out' });
      gsap.to(edgeIntensity, { value: 2.2, duration: 0.18, ease: 'power2.out' });
    },
    onPointerOut: () => {
      pressed = false;
      gsap.to(buttonGroup.position, { z: 0, duration: 0.24, ease: 'power2.out' });
      gsap.to(edgeIntensity, { value: 1.6, duration: 0.24, ease: 'power2.out' });
      gsap.to(buttonGroup.scale, { x: 1, y: 1, z: 1, duration: 0.24, ease: 'power2.out' });
      gsap.to(shadow.scale, { x: 1, y: 1, duration: 0.24, ease: 'power2.out' });
      gsap.to(shadowOpacity, { value: 0.35, duration: 0.24, ease: 'power2.out' });
    },
    onPointerDown: () => {
      pressed = true;
      gsap.to(buttonGroup.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' });
      gsap.to(shadow.scale, { x: 0.88, y: 0.88, duration: 0.12, ease: 'power2.out' });
      gsap.to(shadowOpacity, { value: 0.48, duration: 0.12, ease: 'power2.out' });
    },
    onPointerUp: () => {
      if (!pressed) return;
      pressed = false;
      gsap.to(buttonGroup.scale, { x: 1, y: 1, z: 1, duration: 0.3, ease: 'power4.out' });
      gsap.to(shadow.scale, { x: 1, y: 1, duration: 0.3, ease: 'power2.out' });
      gsap.to(shadowOpacity, { value: 0.35, duration: 0.3, ease: 'power2.out' });
    },
    onClick: () => {
      ctx.emit('cta:begin-commission', { source: config.id ?? 'gradient-cta', to: 'hub-pricing' });
    }
  };

  // ---------------------------------------------------------------
  // CLEANUP
  // ---------------------------------------------------------------
  root.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    gsap.killTweensOf(buttonGroup.position);
    gsap.killTweensOf(buttonGroup.scale);
    gsap.killTweensOf(floatGroup.position);
    gsap.killTweensOf(shadow.scale);
    gsap.killTweensOf(edgeIntensity);
    gsap.killTweensOf(shadowOpacity);
    for (const h of primitiveHandles) h.cleanup && h.cleanup();
    for (const d of disposables) d.dispose && d.dispose();
    root.remove(rim);
    root.remove(fill);
  };

  return root;
}
